const meetingId = $('meeting').first().json.id;
const chunks = $input.first().json.chunks || [];
if (!chunks.length) {
  throw new Error('No audio chunks to transcribe');
}

return chunks.map((chunk, index) => {
  const fileSize = Number(chunk.fileSize);
  if (!Number.isFinite(fileSize) || fileSize < 0) {
    throw new Error(`Audio chunk ${index} is missing fileSize`);
  }
  const fileChunkIndex = Number(chunk.chunkIndex);
  const fileChunkCount = Number(chunk.chunkCount);
  return {
    json: {
      ...chunk,
      fileChunkIndex: Number.isFinite(fileChunkIndex) ? fileChunkIndex : index,
      fileChunkCount: Number.isFinite(fileChunkCount) ? fileChunkCount : chunks.length,
      meetingChunkIndex: index,
      meetingChunkCount: chunks.length,
      chunkIndex: index,
      chunkCount: chunks.length,
      fileSize,
      chunkId: `${meetingId}:${index}:${fileSize}`,
    },
  };
});

const meetingRow = $('meeting').first().json;
const savedTranscript = String(meetingRow.transcription || '').trim();
if (Number(meetingRow.TranscriptionCompleted) === 1 && savedTranscript) {
  return [{
    json: {
      text: savedTranscript,
      chunkCount: 0,
      checkpointCount: 0,
      reusedSavedTranscript: true,
    },
  }];
}

function stitchTranscripts(parts) {
  let result = '';
  for (const part of parts) {
    const text = String(part || '').trim();
    if (!text) continue;
    if (!result) {
      result = text;
      continue;
    }
    const prevWords = result.split(/\s+/).slice(-12).join(' ');
    const windowText = text.slice(0, 1200);
    const at = prevWords ? windowText.indexOf(prevWords) : -1;
    if (at >= 0) {
      const remainder = text.slice(at + prevWords.length).trim();
      result = remainder ? result.trimEnd() + '\n\n' + remainder : result;
    } else {
      result = result.trimEnd() + '\n\n' + text;
    }
  }
  return result.trim();
}

const expected = $('Expand Audio Chunks').all().map((item) => item.json);
if (!expected.length) {
  throw new Error('No expected audio chunks to join');
}

const saved = ($input.first().json.chunks || []);
const byId = {};
for (const row of saved) {
  if (row && row.chunkId && typeof row.text === 'string' && row.text.trim()) {
    byId[row.chunkId] = row.text.trim();
  }
}

const parts = expected.map((chunk) => {
  const text = byId[chunk.chunkId];
  if (!text) {
    throw new Error(`Missing transcript checkpoint for ${chunk.chunkId}`);
  }
  return text;
});

return [{
  json: {
    text: stitchTranscripts(parts),
    chunkCount: parts.length,
    checkpointCount: saved.length,
  },
}];

const saved = $input.first().json.chunks || [];
const savedIds = new Set(
  saved
    .filter((row) => row && row.chunkId && typeof row.text === 'string' && row.text.trim())
    .map((row) => row.chunkId)
);

const pending = $('Expand Audio Chunks')
  .all()
  .filter((item) => !savedIds.has(item.json.chunkId))
  .map((item) => item.json);

if (!pending.length) {
  return [{ json: { noPending: true, pendingCount: 0 } }];
}

return pending.map((chunk, index) => ({
  json: {
    ...chunk,
    pendingIndex: index,
    pendingCount: pending.length,
  },
}));

