const AUTO_ORDER = [{"key": "gemini_flash", "provider": "google", "openrouterId": null, "label": "Gemini Flash"}, {"key": "deepseek_v41_flash", "provider": "openrouter", "openrouterId": "deepseek/deepseek-v4.1-flash", "label": "DeepSeek V4.1 Flash"}, {"key": "glm_53", "provider": "openrouter", "openrouterId": "z-ai/glm-5.3", "label": "GLM-5.3"}, {"key": "qwen38_27b", "provider": "openrouter", "openrouterId": "qwen/qwen3.8-27b", "label": "Qwen3.8 27B"}, {"key": "gemini_4_argon", "provider": "openrouter", "openrouterId": "google/gemini-4-argon", "label": "Gemini 4 Argon"}, {"key": "gpt_61_sol", "provider": "openrouter", "openrouterId": "openai/gpt-6.1-sol", "label": "GPT-6.1 Sol"}, {"key": "claude_sonnet_55", "provider": "openrouter", "openrouterId": "anthropic/claude-sonnet-5.5", "label": "Claude Sonnet 5.5"}, {"key": "gemma4_31b_free", "provider": "openrouter", "openrouterId": "google/gemma-4-31b-it:free", "label": "Gemma 4 31B (free)"}, {"key": "nvidia", "provider": "nvidia", "openrouterId": null, "label": "NVIDIA Nemotron"}];
const MANUAL_FALLBACK = [{"key": "gemma4_31b_free", "provider": "openrouter", "openrouterId": "google/gemma-4-31b-it:free", "label": "Gemma 4 31B (free)"}, {"key": "nvidia", "provider": "nvidia", "openrouterId": null, "label": "NVIDIA Nemotron"}];
const MODEL_BY_KEY = Object.fromEntries(AUTO_ORDER.map((m) => [m.key, m]));

const meeting = $('meeting').first().json || {};
const prompt = $('MeetingSummaryPrompt').first().json || {};
const requested = String(meeting.analyze_model || 'auto').trim() || 'auto';

function orderFor(key) {
  if (!key || key === 'auto' || !MODEL_BY_KEY[key]) {
    return AUTO_ORDER.slice();
  }
  const primary = MODEL_BY_KEY[key];
  const order = [primary];
  for (const fallback of MANUAL_FALLBACK) {
    if (fallback.key === key) continue;
    order.push(fallback);
  }
  return order;
}

const order = orderFor(requested);
return order.map((model, index) => ({
  json: {
    key: model.key,
    provider: model.provider,
    openrouterId: model.openrouterId,
    label: model.label,
    index,
    requested,
    CommentText: prompt.CommentText,
    meetingId: meeting.id,
  },
}));

const REQUIRED = ['Subject', 'Summary', 'People in meetings', 'Bolet Points', 'Tags'];
const current = $('Loop Analyze Models').item.json || {};
const item = $input.first().json || {};
if (item.error) {
  const message = (item.error && (item.error.message || item.error.description)) || 'Analyze failed';
  throw new Error(message);
}
const text = item.candidates && item.candidates[0] && item.candidates[0].content && item.candidates[0].content.parts && item.candidates[0].content.parts[0] && item.candidates[0].content.parts[0].text;
let source = String(text || '').trim();
const fenced = source.match(/```(?:json)?\s*([\s\S]*?)```/i);
if (fenced) source = fenced[1].trim();
let parsed;
try {
  parsed = JSON.parse(source);
} catch (e) {
  parsed = null;
}
if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed) || REQUIRED.some((key) => !Object.prototype.hasOwnProperty.call(parsed, key))) {
  throw new Error((current.label || current.key || 'Model') + ' returned invalid JSON');
}
return [{
  json: {
    ...item,
    analyzedByKey: current.key,
    analyzedByLabel: current.label,
  },
}];

return [{
  json: {
    error: {
      message: 'All configured analyze models failed',
    },
  },
}];
